    }

def __init__(self, obj=None, token=None):
    """
    A "trusted" identity is trusted to be passing in
    the correct account number(s).
    """
    if token:
        # Treat as a trusted identity
        self.token = token
        self.is_trusted_system = True

        # This needs to be moved.
        # The logic for reading the environment variable and logging
        # a warning should go into the Config class
        shared_secret = os.getenv(SHARED_SECRET_ENV_VAR)
        if not shared_secret:
            logger.warning("%s environment variable is not set", SHARED_SECRET_ENV_VAR)
        if self.token != shared_secret:
            raise ValueError("Invalid credentials")

        threadctx.account_number = "<<TRUSTED IDENTITY>>"

    elif obj:
        # Ensure account number availability
        self.is_trusted_system = False
        self.account_number = obj.get("account_number")
        self.auth_type = obj.get("auth_type")
        self.identity_type = obj.get("type")

        if not self.account_number:
            raise ValueError("The account_number is mandatory.")
        elif not self.identity_type or self.identity_type not in IdentityType.__members__.values():
            raise ValueError("Identity type invalid or missing in provided Identity")
        elif self.auth_type and self.auth_type not in AuthType.__members__.values():
            raise ValueError(f"The auth_type {self.auth_type} is invalid")

        if self.identity_type == IdentityType.USER:
            self.user = obj.get("user")

        elif self.identity_type == IdentityType.SYSTEM:
            self.system = obj.get("system")
            if not self.system:
                raise ValueError("The identity.system field is mandatory for system-type identities")
            elif not self.system.get("cert_type"):
                raise ValueError("The cert_type field is mandatory for system-type identities")
            elif self.system.get("cert_type") not in CertType.__members__.values():
                raise ValueError("The cert_type is invalid.")
            elif not self.system.get("cn"):
                raise ValueError("The cn field is mandatory for system-type identities")

        threadctx.account_number = obj["account_number"]

    else:
        raise ValueError("Neither the account_number or token has been set")

def _parse_expression(self, inTemplate: bool) -> ASTExpression:
    # -> assignment-expression
    #  | expression "," assignment-expresion
    expr = self._parse_assignment_expression(inTemplate=inTemplate)
    self.skip_ws()
    if self.skip_string(","):
        second_expr = self._parse_assignment_expression(inTemplate=inTemplate)
        return ASTExpression(expr, second_expr)
    return expr

def query_by_short_id(context, model, short_id, project_safe=True):
    q = model_query(context, model)
    q = q.filter(model.id.like('%s%%' % short_id))

    if project_safe:
        q = q.filter_by(project=context.project)

    if q.count() == 1:
        return q.first()
    elif q.count() == 0:
        return None
    else:
        raise exception.MultipleChoices(arg=short_id)

def _processMessage(self, msg):
    """
    process the msg, and put the result in the output buffer
    msg (str): raw message (including header)
    """
    res = None
    wspaces = msg.count(' ')
    qmarks = msg.count('?')
    tokens = msg.split()
    if ((wspaces > 1) and (qmarks > 0)) or (wspaces > 2) or (qmarks > 1):
        res = "ERROR: Cannot parse this command\n"
    elif qmarks:
        if tokens[0] == "*IDN?":
            res = IDN + '\n'
        elif tokens[0] == "PWR?":
            pin = int(tokens[1])
            if (pin < 0) or (pin > 7):
                res = "ERROR: Out of range pin number\n"
            else:
                ans = (self._i2crcv >> pin) & MASK
                res = str(ans) + '\n'
        else:
            res = "ERROR: Cannot parse this command\n"
    elif wspaces:
        pin = int(tokens[1])
        val = int(tokens[2])
        if tokens[0] == "PWR":
            if (pin < 0) or (pin > 7):
                res = "ERROR: Out of range pin number\n"
            else:
                self._i2crcv = (self._i2crcv & ~(1 << pin)) | ((val << pin) & (1 << pin))
                res = '\n'
        elif tokens[0] == "WMEM":
            # Add support for WMEM command processing here
            res = '\n'
        elif tokens[0] == "RMEM":
            # Add support for RMEM command processing here
            res = '\n'
        else:
            res = "ERROR: Cannot parse this command\n"
    else:
        res = "ERROR: Cannot parse this command\n"

    # add the response end
    if res is not None:
        self._output_buf += res

def version(ctx: click.Context) -> None:
    pulp_ctx: PulpContext = ctx.find_object(PulpContext)

    if ctx.parent and ctx.parent.params["repo_type"] == "file":
        ctx.obj = PulpFileRepositoryVersionContext(pulp_ctx)
    elif ctx.parent and ctx.parent.params["repo_type"] == "pulp":
        ctx.obj = PulpRepositoryContext(pulp_ctx)
    else:
        raise NotImplementedError()

def __init__(self, app, pubsub, *message_types):
    self.PubSub = pubsub
    self.Loop = app.Loop

    for message_type in message_types:
        self.PubSub.subscribe(message_type, self._on_message)

    self.Websockets = set([])

async def cleanup(self):
    for ws in self.Websockets:
        await ws.close(code=WSCloseCode.GOING_AWAY, message='Server shutdown')
